import{X as S,t as R,$ as k,N as b,A as m,W as C,a0 as E,l as r,a1 as L,L as N}from"./index.js";import{i as A}from"./EChart.js";import{N as g,_ as l,O as w,P as v}from"./ubsYearbook.js";const B={cn:{rungs:{usEquity:"美国股票",dm:"发达市场",em:"新兴市场",usBond:"美国长债",usBill:"美国短端",inflation:"通胀（物价）"},axis:"1900 年投入的 1 美元，126 年后的名义终值",tipCagr:"名义年化",tipReal:"实际终值",endpointNote:"年鉴只公布两端与年化，没有逐年路径——所以这里画的是终点，不是曲线。任何把这六个点逐年连起来的画法都是编的。",secondHalf:(e,i,t)=>`但这是两个半场：新兴市场上半世纪被 1917 年俄国革命（俄国占 1900 年全球股市 8%）和战后崩盘打残；从 ${e} 年算起，新兴市场年化 ${i}% 反超发达市场的 ${t}%。`,breadth:e=>`${e} 个拥有连续投资史的国家里，股票全部是最佳资产类；除葡萄牙外，债券全部跑赢短端。`,mReal:"实际年化",mNominal:"名义年化",mSpread:"股票 ÷ 通胀",sourceLabel:"来源",derived:"终值倍数"},tw:{rungs:{usEquity:"美國股票",dm:"已開發市場",em:"新興市場",usBond:"美國長債",usBill:"美國短端",inflation:"通膨（物價）"},axis:"1900 年投入的 1 美元，126 年後的名目終值",tipCagr:"名目年化",tipReal:"實質終值",endpointNote:"年鑑只公布兩端與年化，沒有逐年路徑——所以這裡畫的是終點，不是曲線。任何把這六個點逐年連起來的畫法都是編的。",secondHalf:(e,i,t)=>`但這是兩個半場：新興市場上半世紀被 1917 年俄國革命（俄國占 1900 年全球股市 8%）與戰後崩盤打殘；從 ${e} 年算起，新興市場年化 ${i}% 反超已開發市場的 ${t}%。`,breadth:e=>`${e} 個擁有連續投資史的國家裡，股票全部是最佳資產類；除葡萄牙外，債券全部跑贏短端。`,mReal:"實質年化",mNominal:"名目年化",mSpread:"股票 ÷ 通膨",sourceLabel:"來源",derived:"終值倍數"},en:{rungs:{usEquity:"US equities",dm:"Developed markets",em:"Emerging markets",usBond:"US long bonds",usBill:"US bills",inflation:"Inflation (price level)"},axis:"Nominal terminal value of $1 invested in 1900, after 126 years",tipCagr:"Nominal CAGR",tipReal:"Real terminal value",endpointNote:"The yearbook publishes the endpoints and the annualized rates, not the 126 observations between them. So these are endpoints, not a curve. Any line drawn year-by-year through these six points would be invented.",secondHalf:(e,i,t)=>`But it is a tale of two halves. Emerging markets lost the first one to the 1917 Russian revolution — Russia was 8% of world equity in 1900 — and to the post-war collapses. Measured from ${e}, EM compounded at ${i}% against DM's ${t}%.`,breadth:e=>`Across all ${e} countries with a continuous investment record, equities were the best-performing asset class. Bonds beat bills everywhere except Portugal.`,mReal:"Real CAGR",mNominal:"Nominal CAGR",mSpread:"Equities ÷ inflation",sourceLabel:"Source",derived:"Terminal multiple"},ja:{rungs:{usEquity:"米国株式",dm:"先進国市場",em:"新興国市場",usBond:"米国長期債",usBill:"米国短期債",inflation:"インフレ（物価水準）"},axis:"1900年に投資した1ドルの、126年後の名目終価",tipCagr:"名目年率",tipReal:"実質終価",endpointNote:"年鑑が公表しているのは両端の値と年率であり、その間の126の観測値ではない。したがってこれは終点であって曲線ではない。この6点を年ごとに結んだ線は、すべて捏造になる。",secondHalf:(e,i,t)=>`ただしこれは前後半で姿が違う。新興国市場は前半を1917年のロシア革命（ロシアは1900年の世界株式の8%）と戦後の崩壊で失った。${e}年以降で測ると、新興国の年率${i}%が先進国の${t}%を上回る。`,breadth:e=>`連続した投資記録を持つ${e}か国すべてで、株式が最も優れた資産クラスだった。債券はポルトガルを除くすべての国で短期債を上回っている。`,mReal:"実質年率",mNominal:"名目年率",mSpread:"株式 ÷ インフレ",sourceLabel:"出所",derived:"終価倍率"},es:{rungs:{usEquity:"Renta variable EE. UU.",dm:"Mercados desarrollados",em:"Mercados emergentes",usBond:"Bonos largos EE. UU.",usBill:"Letras EE. UU.",inflation:"Inflación (nivel de precios)"},axis:"Valor nominal final de 1 $ invertido en 1900, tras 126 años",tipCagr:"CAGR nominal",tipReal:"Valor final real",endpointNote:"El anuario publica los extremos y las tasas anualizadas, no las 126 observaciones intermedias. Por eso esto son extremos, no una curva. Cualquier línea trazada año a año entre estos seis puntos sería inventada.",secondHalf:(e,i,t)=>`Pero son dos mitades distintas. Los emergentes perdieron la primera con la revolución rusa de 1917 —Rusia era el 8% de la renta variable mundial en 1900— y con los desplomes de posguerra. Medido desde ${e}, los emergentes componen al ${i}% frente al ${t}% de los desarrollados.`,breadth:e=>`En los ${e} países con un registro de inversión continuo, la renta variable fue la mejor clase de activo. Los bonos superaron a las letras en todos salvo Portugal.`,mReal:"CAGR real",mNominal:"CAGR nominal",mSpread:"Acciones ÷ inflación",sourceLabel:"Fuente",derived:"Múltiplo final"},ko:{rungs:{usEquity:"미국 주식",dm:"선진국 시장",em:"신흥국 시장",usBond:"미국 장기채",usBill:"미국 단기채",inflation:"인플레이션(물가 수준)"},axis:"1900년에 투자한 1달러의 126년 후 명목 최종 가치",tipCagr:"명목 연 수익률",tipReal:"실질 최종 가치",endpointNote:"연감이 공개한 것은 양 끝의 값과 연율이지 그 사이의 126개 관측치가 아니다. 따라서 이것은 끝점이지 곡선이 아니다. 이 여섯 점을 해마다 이은 선은 모두 지어낸 것이 된다.",secondHalf:(e,i,t)=>`다만 전반과 후반의 모습이 다르다. 신흥국은 전반을 1917년 러시아 혁명(러시아는 1900년 세계 주식의 8%)과 전후 붕괴로 잃었다. ${e}년부터 측정하면 신흥국은 연 ${i}%로 선진국의 ${t}%를 앞선다.`,breadth:e=>`연속된 투자 기록을 가진 ${e}개국 전부에서 주식이 최고의 자산군이었다. 채권은 포르투갈을 제외한 모든 나라에서 단기채를 앞섰다.`,mReal:"실질 연 수익률",mNominal:"명목 연 수익률",mSpread:"주식 ÷ 인플레이션",sourceLabel:"출처",derived:"최종 배수"},fr:{rungs:{usEquity:"Actions américaines",dm:"Marchés développés",em:"Marchés émergents",usBond:"Obligations longues US",usBill:"Bons du Trésor US",inflation:"Inflation (niveau des prix)"},axis:"Valeur nominale finale de 1 $ investi en 1900, après 126 ans",tipCagr:"TCAC nominal",tipReal:"Valeur finale réelle",endpointNote:"L'annuaire publie les deux extrémités et les taux annualisés, pas les 126 observations intermédiaires. Ce sont donc des points d'arrivée, pas une courbe. Toute ligne tracée année par année entre ces six points serait inventée.",secondHalf:(e,i,t)=>`Mais l'histoire se joue en deux mi-temps. Les marchés émergents ont perdu la première avec la révolution russe de 1917 — la Russie pesait 8 % des actions mondiales en 1900 — puis avec les effondrements d'après-guerre. Mesurés depuis ${e}, les émergents composent à ${i} % contre ${t} % pour les développés.`,breadth:e=>`Dans les ${e} pays disposant d'un historique d'investissement continu, les actions ont été la meilleure classe d'actifs. Les obligations ont battu les bons du Trésor partout sauf au Portugal.`,mReal:"TCAC réel",mNominal:"TCAC nominal",mSpread:"Actions ÷ inflation",sourceLabel:"Source",derived:"Multiple final"},de:{rungs:{usEquity:"US-Aktien",dm:"Industrieländer",em:"Schwellenländer",usBond:"US-Langläufer",usBill:"US-Geldmarkt",inflation:"Inflation (Preisniveau)"},axis:"Nominaler Endwert von 1 $, investiert 1900, nach 126 Jahren",tipCagr:"Nominale Jahresrendite",tipReal:"Realer Endwert",endpointNote:"Das Jahrbuch veröffentlicht die beiden Endpunkte und die annualisierten Raten, nicht die 126 Beobachtungen dazwischen. Dies sind also Endpunkte, keine Kurve. Jede Linie, die diese sechs Punkte Jahr für Jahr verbindet, wäre erfunden.",secondHalf:(e,i,t)=>`Es sind allerdings zwei Halbzeiten. Die Schwellenländer verloren die erste an die Russische Revolution von 1917 — Russland stellte 1900 8 % der Weltbörsen — und an die Zusammenbrüche der Nachkriegszeit. Ab ${e} gerechnet liegen die Schwellenländer mit ${i} % vor den ${t} % der Industrieländer.`,breadth:e=>`In allen ${e} Ländern mit durchgehender Anlagehistorie waren Aktien die beste Anlageklasse. Anleihen schlugen den Geldmarkt überall außer in Portugal.`,mReal:"Reale Jahresrendite",mNominal:"Nominale Jahresrendite",mSpread:"Aktien ÷ Inflation",sourceLabel:"Quelle",derived:"Endwert-Multiplikator"}},c=e=>e>=100?`$${Math.round(e).toLocaleString("en-US")}`:`$${e}`;function T({kicker:e,title:i,subtitle:t}){const{locale:$}=S(),a=B[$],x=R.useCallback(()=>{const s=k(),u=[...g].sort((n,o)=>n.terminal-o.terminal),f=n=>n==="usEquity"?s.verdant:n==="inflation"?s.oxblood:n==="dm"||n==="em"?s.signal:s.textMuted;return{animation:!1,grid:E({left:128,right:76,top:16,bottom:44}),tooltip:{...C(s),trigger:"item",formatter:n=>{const o=n.dataIndex,d=u[o],h=[`<strong>${a.rungs[d.key]}</strong>`,`${a.derived} · ${c(d.terminal)}`,`${a.tipCagr} · ${d.cagr.toFixed(1)}%`];return d.realTerminal!==void 0&&h.push(`${a.tipReal} · ${c(d.realTerminal)} (${d.realCagr.toFixed(1)}%)`),h.join("<br/>")}},xAxis:{type:"log",min:10,max:3e5,name:a.axis,nameLocation:"middle",nameGap:30,nameTextStyle:{color:s.textMuted,fontSize:m},axisLabel:{color:s.textMuted,fontSize:m,fontFamily:b,formatter:n=>c(n)},axisLine:{lineStyle:{color:s.border}},splitLine:{lineStyle:{color:s.grid}}},yAxis:{type:"category",data:u.map(n=>a.rungs[n.key]),axisLabel:{color:s.text,fontSize:m},axisLine:{lineStyle:{color:s.border}},axisTick:{show:!1}},series:[{type:"bar",data:u.map(n=>({value:n.terminal,itemStyle:{color:f(n.key)},label:{color:f(n.key)}})),barWidth:"58%",label:{show:!0,position:"right",fontSize:m,fontFamily:b,fontWeight:600,formatter:n=>{const o=n.dataIndex;return`${c(u[o].terminal)} · ${u[o].cagr.toFixed(1)}%`}}}]}},[a]),p=g.find(s=>s.key==="usEquity"),y=g.find(s=>s.key==="inflation");return r.jsxs(L,{id:"panel-ubs-asset-ladder",kicker:e,title:i,subtitle:t,children:[r.jsx(A,{option:x,height:340}),r.jsx(N,{dense:!0,items:[{label:`${a.mNominal} · ${a.rungs.usEquity}`,value:`${p.cagr.toFixed(1)}%`,tone:"verdant"},{label:`${a.mReal} · ${a.rungs.usEquity}`,value:`${p.realCagr.toFixed(1)}%`},{label:a.mSpread,value:`${Math.round(p.terminal/y.terminal).toLocaleString("en-US")}×`},{label:`${l.from}+ · ${a.rungs.em}`,value:`${l.emCagr}%`,tone:"verdant"},{label:`${l.from}+ · ${a.rungs.dm}`,value:`${l.dmCagr}%`}]}),r.jsx("div",{style:{fontSize:12,color:"var(--ink-soft)",marginTop:12,lineHeight:1.7},children:a.secondHalf(l.from,l.emCagr,l.dmCagr)}),r.jsx("div",{style:{fontSize:12,color:"var(--ink-soft)",marginTop:8,lineHeight:1.7},children:a.breadth(w.countries)}),r.jsx("div",{style:{fontSize:11,color:"var(--ink-faint)",marginTop:10,lineHeight:1.6},children:a.endpointNote}),r.jsxs("div",{style:{fontSize:11,color:"var(--ink-faint)",marginTop:8,lineHeight:1.6},children:[r.jsx("span",{style:{letterSpacing:"0.12em",textTransform:"uppercase",color:"var(--ink-mute)"},children:a.sourceLabel})," · ","UBS Global Investment Returns Yearbook 2026 (Dimson · Marsh · Staunton) · ",v.cite," · [",v.grade,"]"]})]})}export{T as PanelUbsAssetLadder};
